class TestSecurityHardening:
    """Verify Makefile does not introduce security vulnerabilities."""

    def test_no_hardcoded_credentials(self, makefile_content: str):
        """Makefile must not contain secrets."""
        secrets = ["password", "secret", "token", "api_key", "BEGIN RSA"]
        lower = makefile_content.lower()
        for secret in secrets:
            assert secret not in lower, f"Potential secret found: {secret}"

    def test_no_curl_pipe_bash(self, makefile_content: str):
        """Block dangerous curl|bash patterns."""
        assert "curl" not in makefile_content or "| bash" not in makefile_content, \
            "curl|bash pattern detected"

    def test_no_sudo_in_targets(self, makefile_content: str):
        """Targets must not require sudo (privilege escalation)."""
        for line in makefile_content.splitlines():
            if line.startswith("\t") and "sudo" in line:
                pytest.fail(f"sudo usage in target: {line.strip()}")

    def test_no_rm_rf_on_root(self, makefile_content: str):
        """Prevent catastrophic rm -rf / patterns."""
        assert "rm -rf /" not in makefile_content, "Dangerous rm -rf / detected"
        assert "rm -rf $(" not in makefile_content or "HOME" not in makefile_content, \
            "Potential dangerous rm with variable"

    def test_pinned_dependencies(self, makefile_content: str):
        """If pip is used, versions should be pinned or use constraints."""
        if "pip install" in makefile_content:
            lines = [l for l in makefile_content.splitlines() if "pip install" in l]
            for line in lines:
                # Allow -r requirements.txt or == pins
                assert "-r " in line or "==" in line or "--constraint" in line, \
                    f"Unpinned pip install: {line.strip()}"


